            fprintf(stderr, "Error: key%d exceeds 20-bit limit (max 0xFFFFF)\n", i);
            return 1;
        }
    }

    // Set the keys
    set_keys(keys[0], keys[1], keys[2], keys[3]);

    // Encrypt
