// FEAL F function
uint32_t f_function(uint32_t input_val) {
    uint8_t x[4];
    uint8_t y[4];

    // Extract bytes from input (big-endian)
    for (int i = 0; i < 4; i++) {
        x[i] = input_val & 0xFF;
        input_val >>= 8;
    }

