    y[3] = g(x[3], y[2], 0);
    y[1] = g(x[1]^x[0], y[2], 0);
    y[0] = g(x[0], y[1], 1);
    uint32_t o = 0;
    for (int i = 0; i < 4; i++) o |= (uint32_t)y[i] << (8*i);
    return o;
}
static inline uint32_t expand(uint32_t k){
    return k ^ (k << 16) ^ (k * 12345u);
}
static inline uint64_t enc(uint64_t p){
    uint32_t l = (uint32_t)(p >> 32), r = (uint32_t)p;
