    for (int i = 0; i < 4; i++){
        uint32_t m = f(r ^ K[i]);
        uint32_t t = r;
        r = l ^ m;
        l = t;
    }
    l ^= r;
    return ((uint64_t)r << 32) | l;
}
static inline uint64_t dec(uint64_t c){
    uint32_t R4 = (uint32_t)(c >> 32);
    uint32_t L4 = ((uint32_t)c) ^ R4;
