    for (int i = 3; i >= 0; i--){
        uint32_t nr = l ^ f(r ^ K[i]);
        uint32_t nl = r;
        l = nl; r = nr;
    }
    r ^= l;
    return ((uint64_t)l << 32) | r;
}

typedef struct { uint32_t v, k; } VK;
static int cmpvk(const void *a, const void *b){
    uint32_t x = ((const VK*)a)->v, y = ((const VK*)b)->v;
    return (x > y) - (x < y);
}

